import {makeOriginalWorkbook} from './excel-export.mjs';
import {createQuickEntry,addedCount} from './quick-entry.mjs';
import {PRODUCTS,DOWNTIME,STATUS,today,validDate,validMonth,daysInMonth,decimal,count,emptyPayload,calculate,normSnapshot,monthly,demoData,makeWorkbook} from './team-core.mjs';
import {TEAM_CONFIG} from './team-config.mjs';
const $=s=>document.querySelector(s),root=$('#root'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(n,d=2)=>new Intl.NumberFormat('hu-HU',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n),hrs=c=>number(c/6000),minutes=c=>number(c/100);
const configured=Boolean(/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(TEAM_CONFIG.url)&&TEAM_CONFIG.publishableKey);
let demo=false,session=null,me=null,profiles=[],records=[],audit=[],reportJobs=[],view='day',date=today(),month=date.slice(0,7),selectedEmployee='',query='',group='all',draft=emptyPayload(),dirty=false,busy=false,lastRefresh=null,toastTimer;
let quickController=null;
function notify(text){$('#notification').textContent=text;$('#notification').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#notification').hidden=true,6500);}
function record(){return records.find(r=>r.employee_id===me?.id&&r.work_date===date);}
function loadDraft(){draft=structuredClone(record()?.payload??emptyPayload());dirty=false;}
function leaveDirty(){return !dirty||confirm('A még be nem küldött módosítások elvesznek. Biztosan továbblépsz?');}
function locked(){return Boolean(record()&&record().status!=='draft');}
function safetyBanner(){return demo?'<div class="banner"><strong>BEMUTATÓ MÓD.</strong> Kitalált dolgozók, csak helyi tesztadatok. A nézetváltás nem valódi belépés, és másik telefonra sem szinkronizál. Ide ne írj éles munkahelyi adatot.</div>':'<div class="banner success">Védett csapatnapló · A szerver csak a jogosultságod szerinti adatokat adja vissza.</div>';}
function totalsCards(t){return `<div class="hero"><section class="metric mainmetric"><span>Elszámolt idő</span><strong>${hrs(t.credited)} óra</strong><small>${minutes(t.norm)} normaperc + ${minutes(t.other)} egyéb perc</small></section><section class="metric"><span>Megadott munkaidő</span><strong>${hrs(t.work)} óra</strong><small>${t.ratio===null?'Nincs arány':number(t.ratio,1)+'% időarány'}</small></section><section class="metric"><span>Rögzített darabok</span><strong>${t.upper} / ${t.lower}</strong><small>felső / alsó · ${t.accessory} kiegészítő</small></section></div>`;}
function landing(){
 $('#identity').textContent='Dolgozók és vezetők egy helyen';
 root.innerHTML=`<div class="intro"><p class="eyebrow">KEVESEBB PAPÍR. KÖNNYEBB ELSZÁMOLÁS.</p><h1>A csapat minden munkanapja,<br>egy helyen.</h1><p class="muted">Dolgozói rögzítés, vezetői ellenőrzés és havi táblázat a küldött Excel elrendezése alapján.</p></div><div class="landing"><section class="card"><p class="eyebrow">SAJÁT HOZZÁFÉRÉS</p><h2>Dolgozói belépés</h2><form id="loginForm" class="stack"><label>Dolgozói azonosító<input name="code" autocomplete="username" placeholder="pl. D001" pattern="[A-Za-z0-9_-]{2,32}" required ${configured?'':'disabled'}></label><label>Jelszó<input type="password" name="password" autocomplete="current-password" required ${configured?'':'disabled'}></label><button class="primary full" ${configured?'':'disabled'}>Belépés</button><div id="liveError" role="alert"></div></form><div class="logininfo">${configured?'Saját azonosítódat és jelszavadat a vezetőtől kapod. A jogosultságot a szerver ellenőrzi.':'<strong>Az éles belépés még nincs bekötve.</strong> A Supabase-adattár és a dolgozói fiókok beállítása szükséges. A bemutató ettől függetlenül kipróbálható.'}</div></section><section class="card previewcard"><p class="eyebrow">NÉZD MEG MOST</p><h2>Próbáld ki a folyamatot</h2><p class="muted">Írj fel pár darabot mintadolgozóként, küldd be a napot, majd válts a vezetői nézetre. A havi táblázat ugyanebből a tesztadatból frissül.</p><div class="stack"><button type="button" class="primary" data-demo="demo-001">Dolgozói nézet kipróbálása →</button><button type="button" data-demo="demo-manager">Főnöki nézet kipróbálása →</button></div><p class="notice">A bemutató nem biztonságos többfelhasználós adatbázis, és nem továbbít adatot a főnöködnek.</p></section></div><p class="notice" style="text-align:center"><a href="./index.html">Korábbi, saját eszközre mentő változat</a> · A régi naplót nem módosítja ez az előnézet.</p>`;
}
function startDemo(id){demo=true;session=null;const data=demoData(month);try{const saved=JSON.parse(localStorage.getItem('muszaknaplo.team.demo.v1')||'null');if(saved&&Array.isArray(saved.records)){for(const r of saved.records){if(!data.profiles.some(p=>p.id===r.employee_id)||!validDate(r.work_date)||!Object.hasOwn(STATUS,r.status)||!Number.isInteger(r.version))throw Error();calculate(r.payload,r.norms);}data.records=saved.records;data.audit=Array.isArray(saved.audit)?saved.audit:[];}}catch{}profiles=data.profiles;records=data.records;audit=data.audit;me=profiles.find(p=>p.id===id);selectedEmployee=profiles[0].id;view=me.role==='manager'?'overview':'day';loadDraft();render();}
function saveDemo(){try{localStorage.setItem('muszaknaplo.team.demo.v1',JSON.stringify({records,audit}));}catch{notify('A bemutató mentése nem sikerült. Az adatok csak ebben a megnyitott ablakban maradnak.');}}
function header(){const manager=me.role==='manager';$('#identity').innerHTML=`${esc(me.display_name)}<br><strong>${esc(me.worker_code)} · ${manager?'vezető':'dolgozó'}</strong>`;return `${safetyBanner()}<div class="row between"><div><p class="eyebrow">${manager?'VEZETŐI MUNKAFELÜLET':'SAJÁT MUNKANAPLÓ'}</p><h1>${manager?'Csapatáttekintés':'Mai munkám'}</h1></div><button data-action="logout" class="quiet">${demo?'Kilépés a bemutatóból':'Kijelentkezés'}</button></div>${demo?`<div class="selectrow">${profiles.map(p=>`<button data-demo-switch="${p.id}" class="${me.id===p.id?'active':''}">${esc(p.display_name)}</button>`).join('')}</div>`:''}<nav class="tabs">${(manager?[['overview','Áttekintés'],['sheet','Havi táblázat'],['audit','Módosítások']]:[['day','Napi rögzítés'],['sheet','Saját táblázat']]).map(([id,text])=>`<button class="${view===id?'active':''}" data-view="${id}">${text}</button>`).join('')}${!demo?'<button data-action="password">Jelszócsere</button>':''}</nav>`;}
function cards(){const disabled=locked()?'disabled':'';return PRODUCTS.filter(p=>(draft.counts[p.id]||0)>0).map(p=>`<article class="product ${(draft.counts[p.id]||0)>0?'used':''}"><h3>${esc(p.code)}</h3><small>${esc(p.group)}</small>${p.id==='product_5174'?'<small class="dangertext">7874 / 7877 egyeztetendő</small>':''}<p class="norm">${minutes(record()?.norms[p.id]??p.rate)} perc / db</p><div class="qty"><button type="button" data-delta="-1" data-product="${p.id}" aria-label="${esc(p.code)} mínusz egy" ${(draft.counts[p.id]||0)===0||locked()?'disabled':''}>−</button><input type="text" inputmode="numeric" data-count="${p.id}" value="${draft.counts[p.id]||0}" aria-label="${esc(p.code)} darabszáma" ${disabled}><button class="plus" data-delta="1" data-product="${p.id}" aria-label="${esc(p.code)} plusz egy" ${disabled}>+</button></div></article>`).join('')||'<p class="empty">Még nincs felírt típus. A legördülő listából válassz, majd add hozzá a darabokat.</p>';}
function dayView(){const r=record(),disabled=locked()?'disabled':'';return `<div class="toolbar"><label>Nap<input id="workDate" type="date" value="${date}" min="2000-01-01" max="2199-12-31"></label><label>Elszámoláshoz megadott munkaóra<input id="workHours" type="text" inputmode="decimal" value="${number(draft.workCentiMinutes/6000)}" ${disabled}></label><span class="badge ${r?.status||''}">${STATUS[r?.status]||'Még nincs beküldve'}</span></div><div id="quickEntryHost"></div><div id="totals">${totalsCards(calculate(draft,r?.norms))}</div>${locked()?'<p class="banner success">Ez a nap már be van küldve. Javításhoz a vezető nyithatja újra; a módosítások naplózva lesznek.</p>':''}<h2 class="qe-recorded-title">Ma felírt típusok</h2><div class="products" id="products">${cards()}</div><section class="card sectiontitle"><details><summary>Állásidő és egyéb munka • percben</summary><p class="muted">A külön felírt percek hozzáadódnak az elszámolt időhöz.</p><div class="formgrid">${DOWNTIME.map(d=>`<label>${esc(d.label)}<input type="text" inputmode="decimal" data-downtime="${d.id}" value="${number((draft.downtime[d.id]||0)/100)}" ${disabled}></label>`).join('')}</div></details></section><section class="card"><details><summary>Brazil, Spoiler és megjegyzés</summary><div class="formgrid"><label>Brazil – külön darabjelölés<input id="brazil" type="text" inputmode="numeric" value="${draft.brazilCount}" ${disabled}></label><label>Spoiler<input id="spoiler" maxlength="1000" value="${esc(draft.spoiler)}" ${disabled}></label><label class="span2">Megjegyzés<textarea id="note" maxlength="3000" ${disabled}>${esc(draft.note)}</textarea></label></div><p class="notice">Brazil és Spoiler önálló normaidő hiányában nem ad hozzá becsült perceket.</p></details></section><div class="endbar"><span id="dirtyState">${dirty?'Módosítva – még nincs beküldve':r?'Beküldött bejegyzés':'Még nincs beküldve'}</span><button class="primary" data-action="submit-day" ${disabled}>${demo?'Teszt-nap beküldése':'Nap beküldése a vezetőnek'}</button></div><p class="notice">Nincs automatikus szünetlevonás vagy létszámszorzó. A felírt mennyiségek beküldésig csak ebben az ablakban vannak.</p>`;}
function monthPicker(){const employees=profiles.filter(p=>p.role==='employee');return `<div class="toolbar"><label>Hónap<input id="month" type="month" min="2000-01" max="2199-12" value="${month}"></label>${view==='sheet'&&me.role==='manager'?`<label>Dolgozó<select id="employee">${employees.map(p=>`<option value="${p.id}" ${p.id===selectedEmployee?'selected':''}>${esc(p.worker_code+' · '+p.display_name)}</option>`).join('')}</select></label>`:''}<button data-action="refresh">Frissítés</button><small>${demo?'Helyi bemutató':lastRefresh?'Frissítve: '+new Date(lastRefresh).toLocaleTimeString('hu-HU'):'Még nem frissült'}</small></div>`;}
function overview(){const employees=profiles.filter(p=>p.role==='employee');const all=employees.map(p=>monthly(records,month,p.id));const t={norm:0,other:0,credited:0,work:0,upper:0,lower:0,accessory:0};for(const m of all)for(const k of Object.keys(t))t[k]+=m[k];t.ratio=t.work?t.credited/t.work*100:null;const pending=records.filter(r=>r.work_date.slice(0,7)===month&&r.status==='submitted');return `${monthPicker()}${totalsCards(t)}<section class="card"><div class="row between"><h2>Dolgozónkénti összesítés</h2><span class="badge submitted">${pending.length} nap ellenőrzésre vár</span></div><div class="tablewrap"><table class="data"><thead><tr><th>Dolgozó</th><th>Nap</th><th>Munkaóra</th><th>Elszámolt óra</th><th>Ellenőrzésre vár</th><th></th></tr></thead><tbody>${employees.map(p=>{const m=monthly(records,month,p.id);return `<tr><td><strong>${esc(p.display_name)}</strong><br><small>${esc(p.worker_code)}</small></td><td>${m.records.length}</td><td>${hrs(m.work)}</td><td>${hrs(m.credited)}</td><td>${m.records.filter(r=>r.status==='submitted').length}</td><td><button data-open-worker="${p.id}">Táblázat →</button></td></tr>`;}).join('')}</tbody></table></div><p class="notice">A mentett napok összesítése, nem teljes jelenléti ív. Az üres napokhoz nem feltételezünk hiányzást, szabadságot vagy ledolgozott órát.</p></section><section class="card"><h2>Beküldött napok ellenőrzése</h2>${recordTable(records.filter(r=>r.work_date.slice(0,7)===month).sort((a,b)=>b.work_date.localeCompare(a.work_date)))}</section>${!demo?'<section class="card"><h2>Új dolgozó</h2><p class="muted">Csak dolgozói jogosultság adható itt. Vezetői jogot az adminisztrátor állíthat be.</p><button data-action="new-employee">Dolgozói fiók létrehozása</button></section>':''}`;}
function recordTable(rows){return rows.length?`<div class="tablewrap"><table class="data"><thead><tr><th>Nap / dolgozó</th><th>Elszámolt óra</th><th>Állapot</th><th>Művelet</th></tr></thead><tbody>${rows.map(r=>{const p=profiles.find(p=>p.id===r.employee_id);return `<tr><td>${r.work_date}<br><small>${esc(p?.display_name||'Dolgozó')}</small></td><td>${hrs(calculate(r.payload,r.norms).credited)}</td><td><span class="badge ${r.status}">${STATUS[r.status]}</span></td><td><button data-detail="${r.employee_id}|${r.work_date}">Részletek</button>${me.role==='manager'&&r.status==='submitted'?` <button data-approve="${r.employee_id}|${r.work_date}">Jóváhagyás</button>`:''}${me.role==='manager'&&r.status!=='draft'?` <button class="quiet" data-reopen="${r.employee_id}|${r.work_date}">Javításra vissza</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="empty">Erre a hónapra még nincs beküldött munkanap.</p>';}
function centralReportCard(p){
 if(demo)return '';
 const job=reportJobs.find(j=>j.employee_id===p.id&&j.report_month===month+'-01'),ready=job&&job.generation===job.processed_generation&&job.object_key;
 return `<section class="card"><h2>Központi Excel</h2><p class="muted">${ready?'A szerveren tárolt Excel a legutóbb lekért adatokkal egyezik.':job?'A központi Excel frissítésre vár. A beküldött napok ettől még el vannak mentve.':'Ehhez a hónaphoz még nincs központi Excel.'}</p>${job?.last_error?`<p class="dangertext">${esc(job.last_error)}</p>`:''}<div class="row"><button data-sync-report="${p.id}" ${job?'':'disabled'}>Excel frissítése</button><button data-central="${p.id}" ${ready?'':'disabled'}>Tárolt Excel letöltése</button></div><p class="notice">Védett felhőfájl. Nem írja át a főnök számítógépén már meglévő helyi Excel-fájlt.</p></section>`;
}
async function centralDownload(id){
 const rows=await request('/rest/v1/report_jobs?select=*&employee_id=eq.'+encodeURIComponent(id)+'&report_month=eq.'+month+'-01'),job=rows[0];
 if(!job||job.generation!==job.processed_generation||!job.object_key)throw Error('A központi Excel még frissül.');
 if(!job.object_key.startsWith(id+'/'+month+'/')||!/^[-a-f0-9]+\/\d{4}-\d{2}\/\d+\.xlsx$/.test(job.object_key))throw Error('Hibás fájlhivatkozás.');
 const r=await fetch(TEAM_CONFIG.url+'/storage/v1/object/authenticated/work-reports/'+job.object_key,{cache:'no-store',headers:{apikey:TEAM_CONFIG.publishableKey,Authorization:'Bearer '+session.access_token}});
 if(!r.ok)throw Error('A védett Excel most nem tölthető le.');
 const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='Kozponti_'+(profiles.find(p=>p.id===id)?.worker_code||'dolgozo')+'_'+month+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
function sheetView(){const p=profiles.find(p=>p.id===(me.role==='manager'?selectedEmployee:me.id));if(!p)return monthPicker()+'<p class="empty">Még nincs kiválasztható dolgozó.</p>';const m=monthly(records,month,p.id),n=daysInMonth(month),byDay=new Map(m.records.map(r=>[Number(r.work_date.slice(8)),r]));function line(label,unit,fn,format=x=>x){const values=Array.from({length:n},(_,i)=>byDay.has(i+1)?fn(byDay.get(i+1)):null);return `<tr><th>${esc(label)}</th><td>${esc(unit)}</td>${values.map(v=>`<td>${v===null?'':esc(format(v))}</td>`).join('')}<td class="total">${esc(format(values.reduce((s,v)=>s+(v||0),0)))}</td></tr>`;}
 return `${monthPicker()}${totalsCards(m)}${centralReportCard(p)}<section class="card"><div class="row between"><div><h2>${esc(p.display_name)} havi táblázata</h2><p class="muted">${esc(p.worker_code)} · ${month} · a Toth.xlsx napi oszlopai és terméksorai alapján</p></div><button class="primary" data-export="${p.id}">Eredeti sablon kitöltve – Excel</button></div><p class="banner">${demo?'Az app és a táblázat ugyanazt a helyi tesztadatot mutatja.':'A táblázat a szerveren mentett napokból töltődik.'} A táblázat oldalra görgethető. A letöltött Excel nem önmagát frissítő felhőfájl.</p><div class="tablewrap"><table class="data matrix"><thead><tr><th>Termék / jogcím</th><th>Egység</th>${Array.from({length:n},(_,i)=>'<th>'+(i+1)+'.</th>').join('')}<th>Havi összes</th></tr></thead><tbody>${line('Munkaóra','óra',r=>r.payload.workCentiMinutes/6000,x=>number(x))}${PRODUCTS.map(product=>line(product.code,minutes(product.rate)+' perc/db',r=>r.payload.counts[product.id]||0)).join('')}${DOWNTIME.map(d=>line(d.label,'perc',r=>(r.payload.downtime[d.id]||0)/100,x=>number(x))).join('')}${line('Brazil jelölés','db',r=>r.payload.brazilCount)}${line('Elszámolt idő','óra',r=>calculate(r.payload,r.norms).credited/6000,x=>number(x))}</tbody></table></div><p class="notice">A naphoz tartozó normapillanatképpel számolunk. Az Excel az eredeti sablon formázását őrzi. A Napi_adatok munkalapon a megjegyzések és állapotok, a Normak lapon a történeti darabidők láthatók.</p></section><section class="card"><h2>Napi bejegyzések</h2>${recordTable(m.records)}${me.role==='manager'?`<p class="notice">HR-továbbítás előtt a hiányzó napokat és a jóváhagyásokat ellenőrizni kell. A rendszer nem küld automatikusan e-mailt.</p><button data-export-approved="${p.id}">Csak a jóváhagyott napok Excelje</button>`:''}</section>`;}
function auditView(){return `<section class="card"><h2>Módosítási napló</h2><p class="muted">A beküldés, jóváhagyás és javításra visszaküldés nyoma.</p>${audit.length?`<ul class="activity">${audit.slice().reverse().slice(0,100).map(e=>`<li><strong>${esc(e.action)}</strong> · ${esc(e.work_date||'')}<br>${esc(e.reason||'')}<br><small>${esc(e.actor_name||'Felhasználó')} · ${new Date(e.created_at).toLocaleString('hu-HU')}</small></li>`).join('')}</ul>`:'<p class="empty">Még nincs megjeleníthető módosítás.</p>'}</section>`;}
function render(){quickController=null;if(!me)return landing();root.innerHTML=header()+(view==='day'?dayView():view==='overview'?overview():view==='sheet'?sheetView():auditView());
 const host=$('#quickEntryHost');if(host)quickController=createQuickEntry(host,{products:PRODUCTS,memoryKey:'team.'+me.id,getCount:id=>draft.counts[id]||0,getRate:p=>record()?.norms[p.id]??p.rate,isLocked:()=>locked(),onAdd(id,increment){if(locked()||busy)throw Error('Ez a nap most nem szerkeszthető.');draft.counts[id]=addedCount(draft.counts[id]||0,increment);updateDraftTotals();$('#products').innerHTML=cards();}});
}
function updateDraftTotals(){dirty=true;$('#totals').innerHTML=totalsCards(calculate(draft,record()?.norms));$('#dirtyState').textContent='Módosítva – még nincs beküldve';quickController?.refresh();}
async function request(path,options={},auth=true){
 if(!configured)throw Error('Az éles adatkapcsolat még nincs beállítva.');
 if(auth&&session&&session.expires_at<Date.now()+30000){const resp=await fetch(TEAM_CONFIG.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:TEAM_CONFIG.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!resp.ok)throw Error('A belépés lejárt. Jelentkezz be újra.');const s=await resp.json();session={...s,expires_at:Date.now()+s.expires_in*1000};}
 const response=await fetch(TEAM_CONFIG.url+path,{...options,cache:'no-store',headers:{apikey:TEAM_CONFIG.publishableKey,...(auth?{Authorization:'Bearer '+session?.access_token}:{}),'Content-Type':'application/json',...(options.headers||{})}});
 const data=await response.json().catch(()=>null);if(!response.ok)throw Error(data?.message||data?.error_description||data?.error||'Nem sikerült a kérés.');return data;
}
async function allRows(table,queryString){const out=[];for(let offset=0;offset<100000;offset+=500){const part=await request(`/rest/v1/${table}?${queryString}&limit=500&offset=${offset}`);out.push(...part);if(part.length<500)return out;}throw Error('Túl sok rekord; szűkítsd a lekérést.');}
async function refresh(){if(demo){render();return;}const nextMonth=Number(month.slice(5))===12?`${Number(month.slice(0,4))+1}-01-01`:`${month.slice(0,4)}-${String(Number(month.slice(5))+1).padStart(2,'0')}-01`;const p=await allRows('profiles','select=*&order=worker_code');const r=await allRows('workdays',`select=*&work_date=gte.${month}-01&work_date=lt.${nextMonth}&order=work_date,employee_id`);profiles=p;records=r;if(!selectedEmployee)selectedEmployee=profiles.find(p=>p.role==='employee')?.id||'';if(me.role==='manager')audit=await request('/rest/v1/audit_events?select=*&order=created_at.desc&limit=100').then(x=>x.reverse());reportJobs=await request('/rest/v1/report_jobs?select=*&report_month=eq.'+month+'-01');lastRefresh=new Date().toISOString();if(!dirty)loadDraft();render();}
async function login(form){const code=String(form.get('code')).trim().toLowerCase();if(!/^[a-z0-9_-]{2,32}$/.test(code))throw Error('Hibás dolgozói azonosító.');let s;try{s=await request('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:code+'@'+TEAM_CONFIG.loginDomain,password:form.get('password')})},false);}catch{throw Error('Sikertelen belépés. Ellenőrizd az azonosítót és a jelszót.');}session={...s,expires_at:Date.now()+s.expires_in*1000};const p=await request('/rest/v1/profiles?select=*&id=eq.'+encodeURIComponent(s.user.id));if(p.length!==1||!p[0].active){session=null;throw Error('Ehhez a fiókhoz nincs aktív dolgozói hozzáférés.');}me=p[0];demo=false;view=me.role==='manager'?'overview':'day';selectedEmployee='';await refresh();}
async function submitDay(){if(locked()||busy)return;if([...root.querySelectorAll('input,textarea')].some(e=>!e.reportValidity()))return;const r=record();calculate(draft,r?.norms);busy=true;try{if(demo){const next={employee_id:me.id,work_date:date,status:'submitted',version:(r?.version||0)+1,payload:structuredClone(draft),norms:r?.norms||normSnapshot(),updated_at:new Date().toISOString()};records=records.filter(x=>!(x.employee_id===me.id&&x.work_date===date));records.push(next);audit.push({action:'Teszt-nap beküldve',actor_name:me.display_name,work_date:date,created_at:new Date().toISOString()});saveDemo();dirty=false;render();notify('Teszt-nap elmentve. A főnöki nézetben már látszik.');}else{const saved=await request('/rest/v1/rpc/save_workday',{method:'POST',body:JSON.stringify({p_date:date,p_payload:draft,p_expected:r?.version||0})});records=records.filter(x=>!(x.employee_id===me.id&&x.work_date===date));records.push(saved);dirty=false;render();notify('A napot a szerver átvette.');try{const result=await request('/functions/v1/rebuild-report',{method:'POST',body:JSON.stringify({employee_id:me.id,month:date.slice(0,7)})});notify(result.status==='ready'?'A nap elmentve, a központi havi Excel frissítve.':'A nap elmentve; a központi Excel frissítése még folyamatban van.');}catch{notify('A nap elmentve. Az Excel szinkronja még függőben van; vezetői frissítés szükséges.');}}}finally{busy=false;}}
async function decide(key,action){const [id,day]=key.split('|'),r=records.find(r=>r.employee_id===id&&r.work_date===day);if(!r)return;let reason='';if(action==='reopen'){reason=prompt('Miért kell javítani ezt a napot? (Legalább 3 karakter)')||'';if(reason.trim().length<3)return;}else if(!confirm(day+' jóváhagyása?'))return;
 if(demo){if(me.role!=='manager')throw Error('Vezetői jogosultság szükséges.');r.status=action==='approve'?'approved':'draft';r.version++;audit.push({action:action==='approve'?'Jóváhagyva':'Javításra visszaküldve',work_date:day,reason,actor_name:me.display_name,created_at:new Date().toISOString()});saveDemo();render();}else{await request('/rest/v1/rpc/manager_decide',{method:'POST',body:JSON.stringify({p_employee:id,p_date:day,p_expected:r.version,p_action:action,p_reason:reason})});await refresh();try{await request('/functions/v1/rebuild-report',{method:'POST',body:JSON.stringify({employee_id:id,month:day.slice(0,7)})});}catch{notify('A döntés mentve; a központi Excel frissítése még függőben van.');}}
}
function detail(key){const [id,day]=key.split('|'),r=records.find(r=>r.employee_id===id&&r.work_date===day);if(!r)return;$('#modalContent').innerHTML=`<h2>${day}</h2><p class="muted">${STATUS[r.status]} · ${r.version}. verzió</p><div class="tablewrap"><table class="data"><tbody>${PRODUCTS.filter(p=>r.payload.counts[p.id]).map(p=>`<tr><td>${esc(p.code)}</td><td>${r.payload.counts[p.id]} db</td><td>${minutes(r.payload.counts[p.id]*r.norms[p.id])} perc</td></tr>`).join('')}${DOWNTIME.filter(p=>r.payload.downtime[p.id]).map(p=>`<tr><td>${esc(p.label)}</td><td></td><td>${minutes(r.payload.downtime[p.id])} perc</td></tr>`).join('')}</tbody></table></div><p class="notice">${esc(r.payload.note)}<br>Spoiler: ${esc(r.payload.spoiler)} · Brazil: ${r.payload.brazilCount} db</p><div class="row"><button type="button" data-action="close-modal">Bezárás</button></div>`;$('#modal').showModal();}
async function downloadExcel(id,approvedOnly=false){const p=profiles.find(p=>p.id===id);if(!p)return;const bytes=await makeOriginalWorkbook(p,month,records,{demo,approvedOnly});const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=`${demo?'BEMUTATO_':''}${p.worker_code}_${month}_${approvedOnly?'JOVAHAGYOTT':'TERVEZET'}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function credentialsModal(create){$('#modalContent').innerHTML=`<h2>${create?'Új dolgozói fiók':'Saját jelszó cseréje'}</h2><input type="hidden" name="operation" value="${create?'new':'password'}"><div class="stack">${create?'<label>Dolgozói azonosító<input name="code" pattern="[A-Za-z0-9_-]{2,32}" required></label><label>Név<input name="name" maxlength="80" required></label>':''}<label>${create?'Kezdő jelszó':'Új jelszó'}<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><p class="notice">Legalább 12 karakter. Ne küldd el chatüzenetben, és ne tedd a GitHubra.</p></div><p id="modalError" class="dangertext" role="alert"></p><div class="row"><button type="button" data-action="close-modal">Mégse</button><button class="primary">Mentés</button></div>`;$('#modal').showModal();}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
 if(b.dataset.demo)return startDemo(b.dataset.demo);
 if(b.dataset.demoSwitch){if(leaveDirty()){me=profiles.find(p=>p.id===b.dataset.demoSwitch);view=me.role==='manager'?'overview':'day';loadDraft();render();}return;}
 if(b.dataset.view){if(leaveDirty()){view=b.dataset.view;if(view==='sheet'&&me.role==='employee')selectedEmployee=me.id;loadDraft();render();}return;}
 if(b.dataset.delta){if(locked()||busy)return;const id=b.dataset.product;draft.counts[id]=count(Math.max(0,(draft.counts[id]||0)+Number(b.dataset.delta)));updateDraftTotals();$('#products').innerHTML=cards();return;}
 if(b.dataset.openWorker){selectedEmployee=b.dataset.openWorker;view='sheet';render();return;}
 if(b.dataset.detail)return detail(b.dataset.detail);if(b.dataset.approve)return await decide(b.dataset.approve,'approve');if(b.dataset.reopen)return await decide(b.dataset.reopen,'reopen');
 if(b.dataset.syncReport){const state=await request('/functions/v1/rebuild-report',{method:'POST',body:JSON.stringify({employee_id:b.dataset.syncReport,month})});await refresh();notify(state.status==='ready'?'Központi Excel frissítve.':'Az Excel frissítése még folyamatban van.');return;}if(b.dataset.central)return await centralDownload(b.dataset.central);
 if(b.dataset.export)return await downloadExcel(b.dataset.export);if(b.dataset.exportApproved)return await downloadExcel(b.dataset.exportApproved,true);
 const action=b.dataset.action;if(action==='submit-day')return await submitDay();if(action==='refresh')return await refresh();if(action==='password')return credentialsModal(false);if(action==='new-employee')return credentialsModal(true);
 if(action==='logout'&&leaveDirty()){if(!demo&&session)await request('/auth/v1/logout',{method:'POST'}).catch(()=>{});session=null;me=null;profiles=[];records=[];audit=[];dirty=false;landing();}
 }catch(error){notify(error.message);}});
root.addEventListener('input',e=>{const t=e.target;if(t.closest('.quick-entry'))return;try{if(t.id==='search'){query=t.value;$('#products').innerHTML=cards();return;}if(locked())return;if(t.dataset.count){if(!t.value.trim())return;draft.counts[t.dataset.count]=count(t.value);updateDraftTotals();}else if(t.id==='spoiler'||t.id==='note'){draft[t.id]=t.value;updateDraftTotals();}t.setCustomValidity('');}catch(error){t.setCustomValidity(error.message);}});
root.addEventListener('change',async e=>{const t=e.target;if(t.closest('.quick-entry'))return;try{
 if(t.id==='group'){group=t.value;$('#products').innerHTML=cards();return;}
 if(t.id==='month'){if(!validMonth(t.value))throw Error('Érvénytelen hónap.');month=t.value;return await refresh();}
 if(t.id==='employee'){selectedEmployee=t.value;render();return;}
 if(t.id==='workDate'){if(!validDate(t.value))throw Error('Érvénytelen dátum.');if(leaveDirty()){date=t.value;const changed=month!==date.slice(0,7);month=date.slice(0,7);loadDraft();if(changed&&!demo)await refresh();else render();}else t.value=date;return;}
 if(locked())return;
 if(t.id==='workHours')draft.workCentiMinutes=decimal(t.value,4800)*60;
 else if(t.id==='brazil')draft.brazilCount=count(t.value);
 else if(t.dataset.downtime)draft.downtime[t.dataset.downtime]=decimal(t.value||'0');
 else if(t.dataset.count)draft.counts[t.dataset.count]=count(t.value||'0');
 else return;updateDraftTotals();t.setCustomValidity('');
 }catch(error){t.setCustomValidity?.(error.message);t.reportValidity?.();notify(error.message);}});
root.addEventListener('submit',async e=>{if(e.target.id!=='loginForm')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await login(new FormData(e.target));}catch(error){if($('#liveError'))$('#liveError').textContent=error.message;else notify(error.message);}finally{b.disabled=false;}});
$('#modal').addEventListener('click',e=>{if(e.target.closest('[data-action="close-modal"]'))$('#modal').close();});
$('#modalForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),p=String(f.get('password')||'');try{if(p.length<12||p.length>128)throw Error('A jelszó 12–128 karakter legyen.');if(f.get('operation')==='new'){await request('/functions/v1/manage-employees',{method:'POST',body:JSON.stringify({code:f.get('code'),name:f.get('name'),password:p})});await refresh();}else await request('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:p})});$('#modal').close();$('#modalContent').innerHTML='';notify('Mentve.');}catch(error){$('#modalError').textContent=error.message;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(me&&!demo&&me.role==='manager'&&!document.hidden&&!$('#modal').open)refresh().catch(()=>notify('Az automatikus frissítés nem sikerült; a korábbi adatokat látod.'));},30000);
landing();
